from pathlib import Path
from PIL import Image,ImageOps,ImageDraw
S=Path(__file__).resolve().parent;C=S/'candidate05';R=C/'review';R.mkdir(exist_ok=True);B=S.parents[1]
def row(items,size):
 out=Image.new('RGB',(size[0]*len(items),size[1]+30),'#202020')
 for i,(path,label) in enumerate(items):
  im=ImageOps.contain(Image.open(path).convert('RGB'),size);x=i*size[0];out.paste(im,(x+(size[0]-im.width)//2,30+(size[1]-im.height)//2));ImageDraw.Draw(out).text((x+10,8),label,fill='white')
 return out
row([(B/'reference.png','Owner reference'),(C/'front.png','Actual Blender: one plank only')],(600,600)).save(R/'whole.png')
row([(B/'phase03/wood_sample44/reference_wood_close.png','Owner reference wood'),(C/'grain_close.png','Neutral light, actual Blender'),(C/'warm_grain.png','Temporary warm reference style light')],(650,500)).save(R/'wood_comparison.png')
a=row([(C/'grain_close.png','Normal active, original studio'),(C/'grain_flat_normal_control.png','Diagnostic flat normals')],(650,440));b=row([(C/'grain_close.png','Original studio key'),(C/'grain_opposed_key.png','Key temporarily moved to opposite side')],(650,440));out=Image.new('RGB',(1300,a.height+b.height));out.paste(a,(0,0));out.paste(b,(0,a.height));out.save(R/'depth_diagnostics.png')
a=row([(S/'candidate04/plank_close.png','Preserved material before this pass'),(C/'plank_close.png','Current localized depth and aging pass')],(650,350));b=row([(C/'front.png','Front'),(C/'turn12.png','Turn12'),(C/'turn45.png','Turn45')],(400,350));out=Image.new('RGB',(1300,a.height+b.height),'#202020');out.paste(a,(0,0));out.paste(b,(50,a.height));out.save(R/'refinement_and_turns.png')
(R/'brief.md').write_text("""Scoped fresh visual material review. Open all four listed pictures in one batch, judge pictures only, change nothing. This is exactly ONE existing lower front test plank. Other wood and metal intentionally stay gray. Owner says the prior reddish brown direction is closer and requires refinement rather than restart. Target: semi realistic stylized fantasy wood, believable rugged warm solid aged hardwood with exaggerated physical details grounded in realism. The original reference is visual ground truth. Keep color stable, no orange push. Main requested improvements are physically recessed looking medium grain, clearer raised ridges and brown crevices, interruptions and fractures, chipped edges, flatter resting areas, varied groove depths and widths, subtle worn damage and a less dominant integrated knot. Avoid equally busy carved bands, printed line art, giant knot targets, plastic or photographic noise. Compare neutral AND temporary warm light. Normal control disables only normals. Opposed key moves only the existing key light, then restores it. This material only test preserves original geometry, so no true displaced silhouette or occluding groove shadow is claimed. Do not mistake color contrast alone for sculptural depth. The before and current views use identical neutral camera and light for comparison, but judge current independently against reference rather than only versus the previous material. Small turned stills cannot prove a continuous turn. Reply READY FOR OWNER JUDGMENT: yes or no, then STYLE AND COLOR, DEPTH AND WOOD CHARACTER, VISIBLE ISSUES, LIMITS. Be blunt and concrete. Do not give final badge shippability or phone score, or grade intentionally gray materials. Read no other file.

"""+'\n'.join(str((R/n).resolve()) for n in ['whole.png','wood_comparison.png','depth_diagnostics.png','refinement_and_turns.png'])+'\n')
print(R.resolve())
